-- Synthetic fixtures only. Every change below rolls back.
begin;
create temp table ga_results(name text primary key);grant select,insert on ga_results to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.ga_results values(label);end$$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$declare caught text;begin begin execute sql;exception when others then get stacked diagnostics caught=returned_sqlstate;end;if caught is distinct from code then raise exception 'FAILED % expected % got %',label,code,caught;end if;insert into pg_temp.ga_results values(label);end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::void$$;

set local role authenticated;select pg_temp.claim(2);
select set_config('ga.g1',public.group_command(null,'create',null,'{"offeringId":"60000000-0000-0000-0000-000000000001","name":"M3 synthetic","mode":"online","streamLabel":"Live discussion","streamIcon":"radio","joinUrl":"https://meet.jit.si/fixture","schedules":[{"weekday":2,"time":"18:00","durationMinutes":60}]}')->>'id',true);
select pg_temp.ok((public.group_view(current_setting('ga.g1')::uuid,'detail')->'group'->>'stream_label')='Live discussion','presentation persisted');
select pg_temp.ok((public.group_view(current_setting('ga.g1')::uuid,'detail')->'group'->>'stream_icon')='radio','allowlisted icon persisted');
select set_config('ga.digest',(select md5(jsonb_agg(to_jsonb(s) order by id)::text) from public.group_sessions s where group_id=current_setting('ga.g1')::uuid),true);
select public.group_command(current_setting('ga.g1')::uuid,'edit',1,'{"streamLabel":"Discussion room","streamIcon":"headphones"}');
select pg_temp.ok((select md5(jsonb_agg(to_jsonb(s) order by id)::text)=current_setting('ga.digest') from public.group_sessions s where group_id=current_setting('ga.g1')::uuid),'bubble-only edit preserves entire session rows and IDs');
select public.group_command(current_setting('ga.g1')::uuid,'edit',2,'{"joinUrl":"","applyMeetingDefaults":true}');
select pg_temp.ok((select bool_and(join_url='') from public.group_sessions where group_id=current_setting('ga.g1')::uuid),'future automatic joining URLs updated');
select pg_temp.ok((select join_url='' from public.study_groups where id=current_setting('ga.g1')::uuid),'meeting URL can be cleared');
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',2,'{"streamIcon":"<svg/>"}')$q$,'23514','arbitrary icon rejected');
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',2,'{"streamLabel":null}')$q$,'23514','null label rejected');
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',2,'{"streamLabel":" "}')$q$,'23514','empty label rejected');
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',2,jsonb_build_object('streamLabel',E'line\nbreak'))$q$,'23514','control label rejected');
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',1,'{"streamLabel":"Stale"}')$q$,'PT409','stale presentation edit rejected');
select public.group_command(current_setting('ga.g1')::uuid,'edit',3,'{"mode":"center","location":"Room 4"}');
select pg_temp.ok((select stream_label='Discussion room' and stream_icon='headphones' and mode='center' and location='Room 4' from public.study_groups where id=current_setting('ga.g1')::uuid),'omitted presentation preserved across location edits');
select public.group_command(current_setting('ga.g1')::uuid,'add',4,'{"userId":"10000000-0000-0000-0000-000000000005"}');
select public.group_command(current_setting('ga.g1')::uuid,'staff',5,'{"userId":"10000000-0000-0000-0000-000000000004"}');
select pg_temp.ok(jsonb_array_length(public.group_view(null,'offering:60000000-0000-0000-0000-000000000001')->'rows')=1,'offering filter returns permitted group');
select pg_temp.claim(4);
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',6,'{"streamLabel":"Assistant escalation"}')$q$,'42501','assistant presentation changes denied');
select pg_temp.claim(5);
select pg_temp.ok((public.group_view(current_setting('ga.g1')::uuid,'summary')->'own')='{"attended":0,"absent":0}'::jsonb,'upcoming unmarked is not absent');
select pg_temp.denied($q$select public.group_command(current_setting('ga.g1')::uuid,'edit',5,'{"streamIcon":"video"}')$q$,'42501','student presentation write denied');
select pg_temp.denied($q$select public.group_view(null,'offering:60000000-0000-0000-0000-000000000001')$q$,'42501','student cannot invoke staff offering filter');
reset role;
update public.group_memberships set starts_at=now()-interval '10 days' where group_id=current_setting('ga.g1')::uuid;
set local role authenticated;select pg_temp.claim(2);
select set_config('ga.past',public.group_command(current_setting('ga.g1')::uuid,'one-off',6,jsonb_build_object('title','Past lesson','startsAt',now()-interval '2 days','endsAt',now()-interval '2 days'+interval '2 hours'))->>'sessionId',true);
select public.group_view(current_setting('ga.g1')::uuid,current_setting('ga.past'));
select public.group_command(current_setting('ga.g1')::uuid,'attendance',null,jsonb_build_object('sessionId',current_setting('ga.past'),'sessionVersion',0,'marks',jsonb_build_array(jsonb_build_object('userId','10000000-0000-0000-0000-000000000005','status','attended'))));
select pg_temp.ok((public.group_view(null,'summary')->'staff'->>'attended')::integer=1,'staff counts explicit draft attended');
select pg_temp.claim(5);
select pg_temp.ok((public.group_view(null,'summary')->'own'->>'attended')::integer=0,'student cannot infer unreleased attendance');
select pg_temp.claim(2);
select public.group_command(current_setting('ga.g1')::uuid,'finalize',null,jsonb_build_object('sessionId',current_setting('ga.past'),'sessionVersion',1));
select pg_temp.claim(5);
select pg_temp.ok((public.group_view(null,'summary')->'own'->>'attended')::integer=1,'student finalized attended count correct');
select pg_temp.ok((public.group_view(null,'summary')->'staff')='{"attended":0,"absent":0}'::jsonb,'student staff summary contains no peer marks');
select pg_temp.claim(6);
select pg_temp.ok((public.group_view(null,'summary')->'own')='{"attended":0,"absent":0}'::jsonb,'different student cannot retrieve peer counts');
select pg_temp.denied($q$select public.group_view(current_setting('ga.g1')::uuid,'summary')$q$,'42501','forged group summary denied');
select pg_temp.claim(3);
select pg_temp.ok((public.group_view(null,'summary')->'staff')='{"attended":0,"absent":0}'::jsonb,'other tenant teacher receives no staff counts');
select pg_temp.denied($q$select public.group_view(current_setting('ga.g1')::uuid,'summary')$q$,'42501','cross tenant group summary denied');
select pg_temp.claim(2);
select public.group_command(current_setting('ga.g1')::uuid,'reopen',null,jsonb_build_object('sessionId',current_setting('ga.past'),'sessionVersion',2,'reason','M3 correction'));
select public.group_command(current_setting('ga.g1')::uuid,'attendance',null,jsonb_build_object('sessionId',current_setting('ga.past'),'sessionVersion',3,'marks',jsonb_build_array(jsonb_build_object('userId','10000000-0000-0000-0000-000000000005','status','absent'))));
select public.group_command(current_setting('ga.g1')::uuid,'finalize',null,jsonb_build_object('sessionId',current_setting('ga.past'),'sessionVersion',4));
select public.group_command(current_setting('ga.g1')::uuid,'remove',(select version from public.study_groups where id=current_setting('ga.g1')::uuid),' {"userId":"10000000-0000-0000-0000-000000000005","reason":"Synthetic removal"}');
select pg_temp.claim(5);
select pg_temp.ok((public.group_view(null,'summary')->'own')='{"attended":0,"absent":1}'::jsonb,'own corrected history survives membership removal');
select pg_temp.denied($q$select public.group_view(current_setting('ga.g1')::uuid,'summary')$q$,'42501','former member cannot access group details through summary');
reset role;

-- Local-only published homework fixtures, never connected development data.
insert into public.homework_assignments(id,course_id,offering_id,lesson_id,title,status,family_id,created_by)
 values('e3000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','Pending M3 homework','published','e3000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002');
set local role authenticated;select pg_temp.claim(5);
select pg_temp.ok((public.group_view(null,'summary')->>'pendingHomework')::int=1,'own homework awaiting submission counted');
select pg_temp.claim(6);
select pg_temp.ok((public.group_view(null,'summary')->>'pendingHomework')::int=0,'other offering homework remains private');
reset role;
insert into public.homework_submissions(assignment_id,user_id,number,status,submitted_at) values('e3000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000005',1,'submitted',now());
set local role authenticated;select pg_temp.claim(5);
select pg_temp.ok((public.group_view(null,'summary')->>'pendingHomework')::int=0,'submitted homework no longer pending');
reset role;
-- A new online recurring group with one eligible student tests bounded notices.
set local role authenticated;select pg_temp.claim(2);
select set_config('ga.notice',public.group_command(null,'create',null,'{"offeringId":"60000000-0000-0000-0000-000000000001","name":"M3 joining defaults","mode":"online","joinUrl":"https://meet.jit.si/before","schedules":[{"weekday":2,"time":"18:00","durationMinutes":60},{"weekday":6,"time":"16:00","durationMinutes":60}]}')->>'id',true);
select public.group_command(current_setting('ga.notice')::uuid,'add',1,'{"userId":"10000000-0000-0000-0000-000000000005"}');
reset role;
select set_config('ga.notices',(select count(*)::text from public.notifications where recipient_id='10000000-0000-0000-0000-000000000005'),true);
set local role authenticated;select pg_temp.claim(2);
select public.group_command(current_setting('ga.notice')::uuid,'edit',2,'{"joinUrl":"https://meet.jit.si/after","applyMeetingDefaults":true}');
reset role;
select pg_temp.ok((select count(*)-current_setting('ga.notices')::int between 0 and 1 from public.notifications where recipient_id='10000000-0000-0000-0000-000000000005'),'future recurring defaults do not flood recipient');
select pg_temp.ok((select count(*)>20 and bool_and(join_url='https://meet.jit.si/after') from public.group_sessions where group_id=current_setting('ga.notice')::uuid),'all future automatic sessions keep IDs with new joining default');

select pg_temp.ok(not has_table_privilege('authenticated','public.study_groups','update'),'direct metadata table write remains revoked');
select pg_temp.ok(not has_function_privilege('anon','public.group_view(uuid,text,integer,text)','execute'),'anonymous summary RPC remains denied');
select pg_temp.ok(has_function_privilege('authenticated','private.group_view(uuid,text,integer,text)','execute'),'existing authenticated wrapper delegation preserved');
select pg_temp.ok(not has_function_privilege('authenticated','public.create_organization(text,text)','execute'),'organization provisioning restriction preserved');
select count(*) as milestone3_group_tests from ga_results;
rollback;
